int dbCalls = 0;
bool Database() { dbCalls++; return false; } // overloaded: every call fails

// A layer calls the one below it up to `attempts` times
Func<bool> Layer(Func<bool> below, int attempts) =>
    () => Enumerable.Range(0, attempts).Any(_ => below());

// Gateway -> Orders -> Inventory -> Database, 3 attempts per hop
Layer(Layer(Layer(Database, 3), 3), 3)();
Console.WriteLine($"Every layer retries: {dbCalls} database calls");

dbCalls = 0;
Layer(Layer(Layer(Database, 3), 1), 1)(); // only Inventory retries
Console.WriteLine($"One layer retries:   {dbCalls} database calls");

