// Orders service. Gateway and Inventory have the same loop
public sealed class InventoryClient(HttpClient http)
{
    public async Task<Stock> GetStockAsync(string sku, CancellationToken ct)
    {
        for (int attempt = 1; ; attempt++)
        {
            try { return (await http.GetFromJsonAsync<Stock>($"/stock/{sku}", ct))!; }
            catch (Exception) when (attempt < 3) // retries 404s too
            {
                await Task.Delay(1000, ct); // every client wakes up together
            }
        }
    }
}

using System.Net;

// Only Orders retries Inventory; Gateway and Inventory fail fast
public sealed class InventoryClient(HttpClient http, RetryBudget budget)
{
    public async Task<Stock> GetStockAsync(string sku, CancellationToken ct)
    {
        budget.OnRequest();
        for (int attempt = 1; ; attempt++)
        {
            try { return (await http.GetFromJsonAsync<Stock>($"/stock/{sku}", ct))!; }
            catch (HttpRequestException e) when (attempt < 3
                && e.StatusCode is null or >= HttpStatusCode.InternalServerError
                && budget.TrySpend()) // false when the budget is spent
            {
                // Full jitter: a random wait up to the capped exponential delay
                double capMs = Math.Min(2_000, 100 * Math.Pow(2, attempt));
                var waitMs = Random.Shared.NextDouble() * capMs;
                await Task.Delay(TimeSpan.FromMilliseconds(waitMs), ct);
            }
        }
    }
}
